-- quest var packing: v = qid * 10000 + (step + 1) * 100 + cnt ; step -1 = not taken, PT45_DONE = finished
function PT45_Q(var)
	local v = GetTask(var)
	return floor(v / 10000), mod(floor(v / 100), 100) - 1, mod(v, 100)
end

function PT45_SetQ(var, qid, step, cnt)
	SetTask(var, qid * 10000 + (step + 1) * 100 + (cnt or 0))
end

function PT45_Today()
	local d = 0
	if date then
		d = tonumber(date("%y%m%d"))
	end
	if d == nil or d <= 0 then d = floor(SystemTime() / 86400) end
	return mod(d, 1000000)
end

-- daily var: day * 100 + rounds * 10 + step
function PT45_Daily(var)
	local v = GetTask(var)
	if floor(v / 100) ~= PT45_Today() then return 0, 0 end
	return mod(floor(v / 10), 10), mod(v, 10)
end

function PT45_SetDaily(var, rounds, step)
	SetTask(var, PT45_Today() * 100 + rounds * 10 + step)
end

