-- La Ban phap tran (VNG item\giai chu phu polygon, map 75 cells)
function PT45_InCompass()
	local m, x, y = GetWorldPos()
	if m ~= PT45_MAP4 then return nil end
	local P = PT45_POLY
	local k = 0
	local j = 1
	while j <= 4 do
		local n = j + 1
		if n > 4 then n = 1 end
		local y1 = P[j * 2]
		local y2 = P[n * 2]
		if y1 ~= y2 then
			local lo = y1
			local hi = y2
			if lo > hi then lo = y2 hi = y1 end
			if y >= lo and y < hi then
				local x1 = (y - y1) * (P[n * 2 - 1] - P[j * 2 - 1]) / (y2 - y1) + P[j * 2 - 1]
				if x1 > x then k = k + 1 end
			end
		end
		j = j + 1
	end
	if mod(k, 2) == 1 then return 1 end
	return nil
end
PT45_POLY = { 1804, 3514, 1925, 3469, 1930, 3362, 1827, 3380 }

-- compass state (VNG layout of 1465): byte1 = state, word2 = password (N*1000+E*100+S*10+W, digits 0..7)
function PT45_Cmp()
	local v = GetTask(PT45_T_CMP)
	return mod(v, 256), floor(v / 65536)
end

function PT45_SetCmp(st, pwd)
	SetTask(PT45_T_CMP, st + pwd * 65536)
end

-- 1466 = asked-pillar mask (bits 1 N, 2 E, 4 S, 8 W) + 16 * rotations (N*512 + E*64 + S*8 + W)
function PT45_Cmp2()
	local v = GetTask(PT45_T_CMP2)
	return mod(v, 16), floor(v / 16)
end

function PT45_SetCmp2(mask, rot)
	SetTask(PT45_T_CMP2, mask + rot * 16)
end

function PT45_Digit(num, k)
	local d = 1000
	local i = 1
	while i < k do d = floor(d / 10) i = i + 1 end
	return mod(floor(num / d), 10)
end

function PT45_RotDigit(rot, k)
	local d = 512
	local i = 1
	while i < k do d = floor(d / 8) i = i + 1 end
	return mod(floor(rot / d), 8)
end

function PT45_RotSet(rot, k, val)
	local d = 512
	local i = 1
	while i < k do d = floor(d / 8) i = i + 1 end
	local old = mod(floor(rot / d), 8)
	return rot + (val - old) * d
end

