-- personal summon beside the player: owner = player id (param 0), kind (param 1), species (param 2)
function PT45_Summon(tpl, lv, name, sp, secs, dx, dy)
	local m, x, y = GetWorldPos()
	local sw = SubWorldID2Idx(m)
	if sw == nil or sw < 0 then return 0 end
	local ni = AddNpc(tpl, lv, sw, (x + (dx or 3)) * 32, (y + (dy or 3)) * 32, 1)
	if ni == nil or ni <= 0 then ni = AddNpc(tpl, lv, sw, x * 32, y * 32, 1) end
	if ni == nil or ni <= 0 then return 0 end
	SetNpcName(ni, name)
	SetNpcScript(ni, PT45_MOB)
	SetNpcParam(ni, 0, GetPlayerID())
	SetNpcParam(ni, 1, PT45_K_SUMMON)
	SetNpcParam(ni, 2, sp)
	SetNpcTimeout(ni, (secs or 300) * 18)
	SetTask(PT45_T_SUMMON, ni)
	return ni
end

function PT45_Alive(sp)
	local ni = GetTask(PT45_T_SUMMON)
	if ni > 0 and GetNpcParam(ni, 1) == PT45_K_SUMMON and GetNpcParam(ni, 2) == sp and GetNpcParam(ni, 0) == GetPlayerID() then return ni end
	return 0
end

