-- credit for the current PlayerIndex
function PT45_KillOne(sp)
	PT45_KillMain(sp)
	if sp <= 30 and (PT45_Is1075(sp) or sp >= 11) then
		PT45_Kill104_108(sp)
		PT45_KillYen(sp)
		PT45_KillMisc4(sp)
		PT45_KillRep4(sp)
	end
	if PT45_Is1076(sp) or sp == PT45_SP_LH or sp == PT45_SP_TLCL or sp == PT45_SP_KGM or sp == PT45_SP_CTH or sp == PT45_SP_CH then
		PT45_Kill5(sp)
	end
end

-- killer and the team members on the same map get the credit
function PT45_OnKill(sp)
	local me = PlayerIndex
	local n = 0
	if GetTeamSize then n = GetTeamSize() end
	if n and n > 1 then
		local w = GetWorldPos()
		local i = 1
		while i <= n do
			local p = GetTeamMember(i)
			if p and p > 0 then
				PlayerIndex = p
				if GetWorldPos() == w then PT45_KillOne(sp) end
			end
			i = i + 1
		end
		PlayerIndex = me
	else
		PT45_KillOne(sp)
	end
end

function PT45_AutoDeath(npc)
	local k = GetNpcParam(npc, 1)
	if k == PT45_K_PACK or k == PT45_K_SUMMON or k == 7701 or k == 7702 or k == 7703 then return end
	if PlayerIndex == nil or PlayerIndex <= 0 then return end
	local m = GetWorldPos()
	if m == PT45_MAP4 then PT45_OnKill(0) elseif m == PT45_MAP5 then PT45_OnKill(50) end
end

